SELECT brand, DATE_TRUNC('QUARTER', launch_date) AS quarter_start, COUNT(DISTINCT category) AS distinct_categories, COUNT(CASE WHEN brand = 'Acme' THEN 1 END) AS acme_count, SUM(CASE WHEN brand = 'Initech' THEN cost ELSE 0 END) AS initech_cost, PERCENT_RANK() OVER (PARTITION BY brand ORDER BY COUNT(DISTINCT category) DESC) AS distinct_categories_percent_rank FROM products GROUP BY 1, 2;
